class Solution {
public:
    long long beautifulSubarrays(vector<int>& nums) {
        unordered_map<int,int> seen;
        seen[0] = 1;
        int px = 0;
        long long ans = 0;
        for (int x : nums) {
            px ^= x;
            auto it = seen.find(px);
            if (it != seen.end()) {
                ans += it->second;
                it->second += 1;
            } else {
                seen[px] = 1;
            }
        }
        return ans;
    }
};
